'use strict';

const fs = require('fs');

const readNum = (name) => {
  if (!fs.existsSync(name)) {
    throw new Error(`missing required file: ${name}`);
  }
  const raw = fs.readFileSync(name, 'utf8').trim();
  if (raw === '') {
    throw new Error(`empty required file: ${name}`);
  }
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new Error(`non-numeric value in ${name}: ${JSON.stringify(raw)}`);
  }
  return value;
};

const seed = readNum('seed.txt');
const stage1 = readNum('stage1.txt');
const stage2 = readNum('stage2.txt');
const stage3 = readNum('stage3.txt');

const checks = [
  ['stage1 === seed + 2', stage1, seed + 2],
  ['stage2 === stage1 * stage1', stage2, stage1 * stage1],
  ['stage3 === stage2 - 4', stage3, stage2 - 4],
];

let ok = true;
for (const [label, actual, expected] of checks) {
  const pass = actual === expected;
  if (!pass) ok = false;
  console.log(`${pass ? 'PASS' : 'FAIL'} ${label}: ${actual} vs expected ${expected}`);
}

console.log(`seed=${seed} stage1=${stage1} stage2=${stage2} stage3=${stage3}`);

if (!ok) {
  throw new Error('stage verification failed; answer.json not written');
}

const answer = { stage1, stage2, stage3 };
fs.writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\n', 'utf8');
console.log('wrote answer.json');
